import React from 'react';
import { BrowserRouter } from 'react-router-dom';
import AppRoutes from './routes';
import { ApiProvider } from './context/ApiContext'; 

function App() {
  return (
    <BrowserRouter>
      <ApiProvider>
        <AppRoutes />
      </ApiProvider>
    </BrowserRouter>
  );
}

export default App;
