import React, { useState, useEffect } from 'react';
import mainBackground from '../assets/img/themes/bg_panoramic.jpg';
import logo from '../assets/img/themes/logo.png';
import Banner from './Banner';
import MobileBanner from './MobileBanner';
import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import { Navigation, Pagination, Mousewheel, Keyboard } from 'swiper/modules';
import frame from '../assets/img/themes/frame.png';
import leftArrow from '../assets/img/themes/leftarrow.png';
import rightArrow from '../assets/img/themes/rightarrow.png';
import useApi from '../hooks/useApi';
import { useSelector, useDispatch } from 'react-redux';
import { setLoading, setGamePlayed } from '../store/reducers/gameSlice';
import MiddlePart from './MiddlePart';
import IconMenu from './IconMenu';

const GridItem = ({ gameId, onGameClick }) => (
    <div
        className="relative h-[21vh] cursor-pointer hover:opacity-90 transition-opacity min-h-[29%] md:min-h-[23%]"
        onClick={() => onGameClick(gameId)}
    >
        <div className="absolute w-full inset-0 bg-cover bg-center bg-no-repeat rounded-[20px]" style={{ backgroundImage: `url(${process.env.REACT_APP_SERVER_URL}/thumbnails/225x140/${gameId}.jpg)` }}>
            <img src={frame} alt="frame" className="w-full h-full object-fill" />
        </div>
    </div>
);

const generateGridItems = (games = [], onGameClick) => {
    const items = games.map((game, index) => <GridItem key={game.Id || index} gameId={game.Id} onGameClick={onGameClick} />);

    items.push(
        <div
            key="empty-child"
            className="relative h-[21vh]"
            style={{ minHeight: "200px" }}
        >
            <div className="absolute w-full inset-0">
            </div>
        </div>
    );

    return items;
};

const MainContent = () => {
    const Api = useApi();
    const [gameList, setGameList] = useState([]);
    const [error, setError] = useState(null);
    const [gameUrl, setGameUrl] = useState("");
    const dispatch = useDispatch();
    const { loading, gamePlayed } = useSelector((state) => state.games);
    const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
    const currentHeight = window.innerHeight;
    const TmpMt = currentHeight * 0.2227;
    const logoHeight = currentHeight * 0.126;
    // console.log("TmpMt, TmpMb",TmpMt, TmpMb);

    useEffect(() => {
        const handleResize = () => {
            setIsMobile(window.innerWidth < 768);
        };

        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    useEffect(() => {
        const fetchGameList = async () => {
            try {
                dispatch(setLoading(true));
                const response = await Api.getGameList();
                setGameList(response.data);
                dispatch(setLoading(false));
            } catch (error) {
                dispatch(setError(error));
                dispatch(setLoading(false));
            }
        }
        fetchGameList();
    }, [Api]);

    const handleGameClick = async (gameId) => {
        try {
            const response = await Api.triggerGame("GoldenBet_USD", gameId);

            if (response?.data?.result?.SessionUrl) {
                const fullUrl = response.data.result.SessionUrl;

                setGameUrl(fullUrl);
                dispatch(setGamePlayed(true));
            } else {
                console.error('No URL found in response:', response);
            }
        } catch (error) {
            console.error('Error triggering game:', error);
            console.error('Error details:', {
                message: error.message,
                response: error.response?.data,
                status: error.response?.status
            });
        }
    };

    const slides = [
        {
            id: 1,
            content: <div className="grid grid-cols-4 gap-x-4 gap-y-8 md:px-12 lg:px-24 py-8 max-h-[800px]:py-8 h-full mx-[30px]">
                {generateGridItems(gameList.result?.slice(0, 8), handleGameClick)}
            </div>
        },
        {
            id: 2,
            content: <div className="grid grid-cols-4 gap-x-4 gap-y-8 md:px-12 lg:px-24 py-8 max-h-[800px]:py-8 h-full mx-[30px]">
                {generateGridItems(gameList.result?.slice(8, 16), handleGameClick)}
            </div>
        },
        {
            id: 3,
            content: <div className="grid grid-cols-4 gap-x-4 gap-y-8 md:px-12 lg:px-24 py-8 max-h-[800px]:py-8 h-full mx-[30px]">
                {generateGridItems(gameList.result?.slice(16, 20), handleGameClick)}
            </div>
        },
    ];

    return (
        <main className="relative flex flex-col w-full lg:h-[calc(100dvh-62px)] overflow-hidden">
            {gamePlayed ? (
                <div className="relative w-full android:h-full md:h-full">
                    {window.navigator.userAgent.includes('Android') ? (
                        <iframe
                            src={gameUrl}
                            className="w-full border-none h-screen overflow-hidden"
                            title="Game Frame"
                            allow='fullscreen'
                        />
                    ) : window.navigator.userAgent.includes('iPhone') || window.navigator.userAgent.includes('iPad') ? (
                        <iframe
                            src={gameUrl}
                            className="w-full border-none h-[-webkit-fill-available] overflow-hidden"
                            title="Game Frame"
                            allow='fullscreen'
                        />
                    ) : (
                        <iframe
                            src={gameUrl}
                            className="w-full border-none h-full overflow-hidden"
                            title="Game Frame"
                            allow='fullscreen'
                        />
                    )}

                    <button
                        onClick={() => dispatch(setGamePlayed(false))}
                        className="block md:hidden fixed top-5 right-5 p-2 z-50"
                    >
                        🏠
                    </button>

                    <button
                        onClick={() => dispatch(setGamePlayed(false))}
                        className="hidden md:block fixed"
                        style={{
                            top: 'calc(env(safe-area-inset-top) + 20px)',
                            right: 'calc(env(safe-area-inset-right) + 20px)',
                            zIndex: 1000
                        }}
                    >
                        Exit Game
                    </button>
                </div>
                // <div className="relative w-full h-full"
                //     style={{
                //         padding: 'env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left)',
                //         height: '100dvh'
                //     }}>
                //     <iframe
                //         src={gameUrl}
                //         className="w-full h-[calc(100dvh-10px)]"
                //         title="Game Frame"
                //         allow='fullscreen'
                //         style={{
                //             height: '-webkit-fill-available',
                //             overflow: 'hidden'
                //         }}
                //     />

                //     <button
                //         onClick={() => dispatch(setGamePlayed(false))}
                //         className="block md:hidden fixed"
                //         style={{
                //             top: 'calc(env(safe-area-inset-top) + 20px)',
                //             right: 'calc(env(safe-area-inset-right) + 20px)',
                //             zIndex: 1000
                //         }}
                //     >
                //         🏠
                //     </button>


                //     <button
                //         onClick={() => dispatch(setGamePlayed(false))}
                //         className="hidden md:block fixed"
                //         style={{
                //             top: 'calc(env(safe-area-inset-top) + 20px)',
                //             right: 'calc(env(safe-area-inset-right) + 20px)',
                //             zIndex: 1000
                //         }}
                //     >
                //         Exit Game
                //     </button>
                // </div>
            ) : (
                <>
                    <div
                        className="absolute inset-0 w-full h-screen animate-zoomEffect"
                        style={{
                            backgroundImage: `url(${mainBackground})`,
                            backgroundSize: 'cover',
                            backgroundPosition: 'center',
                            backgroundRepeat: 'no-repeat'
                        }}
                    />
                    <div className="z-10 h-auto md:mt-0">
                        <Banner className="hidden lg:flex" />
                        <div className="hidden md:flex md:flex-col w-full items-center">
                            <img src={logo} alt="logo" className="w-[42%] mt-[-10px]" style={{ height: `${logoHeight}px` }} />
                        </div>
                        <Banner className="hidden md:flex lg:hidden" />
                    </div>

                    <div className="hidden md:block pt-[0px] max-h-[800px]:pt-[48px] h-screen md:h-[58.7%]">
                        <Swiper
                            csmdode={true}
                            navigation={{
                                nextEl: '.swiper-button-next',
                                prevEl: '.swiper-button-prev',
                            }}
                            pagination={false}
                            mousewheel={true}
                            keyboard={true}
                            loop={true}
                            modules={[Navigation, Pagination, Mousewheel, Keyboard]}
                            className="mySwiper h-full [&_.swiper-button-next:after]:hidden [&_.swiper-button-prev:after]:hidden [&_.swiper-button-next]:w-[7%] [&_.swiper-button-prev]:w-[7%] [&_.swiper-button-next]:h-[7rem] [&_.swiper-button-prev]:h-[7rem] [&_.swiper-button-next]:bg-contain [&_.swiper-button-prev]:bg-contain [&_.swiper-button-next]:bg-no-repeat [&_.swiper-button-prev]:bg-no-repeat [&_.swiper-button-next]:bg-center [&_.swiper-button-prev]:bg-center [&_.swiper-button-next]:right-0 [&_.swiper-button-prev]:left-0 [&_.swiper-button-next]:top-1/2 [&_.swiper-button-prev]:top-1/2 [&_.swiper-button-next]:-translate-y-1/2 [&_.swiper-button-prev]:-translate-y-1/2"
                        >
                            {slides.map(slide => (
                                <SwiperSlide key={slide.id}>
                                    {slide.content}
                                </SwiperSlide>
                            ))}
                            <div className="swiper-button-prev bg-contain bg-no-repeat bg-center" style={{ backgroundImage: `url(${leftArrow})` }}>
                            </div>
                            <div className="swiper-button-next bg-contain bg-no-repeat bg-center" style={{ backgroundImage: `url(${rightArrow})` }}>
                            </div>
                        </Swiper>
                    </div>

                    <div className='flex flex-col gap-8 md:hidden px-[13.5%] overflow-y-scroll'
                        style={{
                            ...(isMobile ? {
                                marginTop: `${TmpMt}px`
                            } : {})
                        }}
                    >
                        {generateGridItems(gameList.result, handleGameClick)}
                    </div>

                    <IconMenu />
                    <MiddlePart />
                </>
            )}
        </main>
    );
};

export default MainContent;
